INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('50f1689c-f250-4f15-870a-89b443a270d5', 'c1c2c3d4-3030-4000-8000-000000000030', 6, 'Silenciar', 'Semana 1 — Despertar', '{"pch": "No sil\u00eancio\u2026 a verdade sobe.", "verse": "1Rs 19,11-13", "lectio": "Fique 5 minutos em sil\u00eancio antes de ler. O que surgiu?", "practice": "Reserve 10 minutos de sil\u00eancio completo hoje.", "question": "O que aparece quando voc\u00ea para?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('0288ddc5-3827-4163-be3a-5e8e4458e3bb', 'c1c2c3d4-3030-4000-8000-000000000030', 7, 'Observar', 'Semana 1 — Despertar', '{"pch": "Voc\u00ea n\u00e3o \u00e9 o pensamento\u2026 \u00e9 quem percebe.", "verse": "Lc 12,22-26", "lectio": "Leia e observe: quais pensamentos autom\u00e1ticos governam suas decis\u00f5es?", "practice": "Anote 3 pensamentos recorrentes que podem ser cren\u00e7as, n\u00e3o verdades.", "question": "O que voc\u00ea est\u00e1 acreditando sem questionar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b012f24c-4a6b-4fbb-9076-34f2909d1246', 'c1c2c3d4-3030-4000-8000-000000000030', 8, 'Soltar Controle', 'Semana 2 — Desconstruir', '{"pch": "Controlar \u00e9 a forma mais elegante de desconfiar.", "verse": "Pv 3,5-6", "lectio": "Leia e pergunte: em que \u00e1rea eu confio mais em mim do que em Deus?", "practice": "Escolha uma coisa para n\u00e3o controlar hoje. Observe o que sente.", "question": "O que voc\u00ea n\u00e3o consegue largar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('ab2806d7-2b4c-43b2-a7e4-c491681c8b11', 'c1c2c3d4-3030-4000-8000-000000000030', 9, 'Enfrentar Medo', 'Semana 2 — Desconstruir', '{"pch": "O medo n\u00e3o \u00e9 sinal de fraqueza\u2026 \u00e9 sinal de fronteira.", "verse": "Is 41,10", "lectio": "Leia a promessa. Pergunte: qual medo Deus est\u00e1 me convidando a atravessar?", "practice": "Nomeie seu maior medo atual e escreva o que aconteceria se ele n\u00e3o existisse.", "question": "Qual medo te paralisa?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c6550de4-ada8-4202-b793-7b28ad948975', 'c1c2c3d4-3030-4000-8000-000000000030', 10, 'Identificar Padrões', 'Semana 2 — Desconstruir', '{"pch": "Voc\u00ea chama de personalidade\u2026 mas pode ser repeti\u00e7\u00e3o.", "verse": "Rm 7,15-20", "lectio": "Paulo descreve a luta interior. Qual luta \u00e9 sua?", "practice": "Identifique um padr\u00e3o que se repete em relacionamentos, trabalho ou emo\u00e7\u00f5es.", "question": "Qual padr\u00e3o voc\u00ea repete sem perceber?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('698dfc1a-e44e-42d0-b4fe-66fc6f0cdc37', 'c1c2c3d4-3030-4000-8000-000000000030', 11, 'Romper Crenças', 'Semana 2 — Desconstruir', '{"pch": "A verdade liberta\u2026 mas primeiro incomoda.", "verse": "Jo 8,32", "lectio": "Leia e pergunte: qual mentira eu acreditei sobre mim?", "practice": "Escreva uma cren\u00e7a limitante e reescreva-a \u00e0 luz da Palavra.", "question": "Qual cren\u00e7a sobre voc\u00ea mesmo precisa ser revisada?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('4affb73b-d4d7-4845-b7cc-a5c1f89739a5', 'c1c2c3d4-3030-4000-8000-000000000030', 12, 'Perdoar', 'Semana 2 — Desconstruir', '{"pch": "Perdoar n\u00e3o \u00e9 esquecer\u2026 \u00e9 soltar a corda que te prende ao outro.", "verse": "Mt 6,14-15", "lectio": "Leia e sinta: qual peso do passado voc\u00ea ainda carrega?", "practice": "Escreva uma carta de perd\u00e3o \u2014 n\u00e3o precisa enviar.", "question": "Quem voc\u00ea ainda n\u00e3o perdoou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3a39399b-5772-45fb-b820-48aff4098714', 'c1c2c3d4-3030-4000-8000-000000000030', 13, 'Liberar Peso', 'Semana 2 — Desconstruir', '{"pch": "Carregar demais n\u00e3o \u00e9 for\u00e7a\u2026 \u00e9 desconfian\u00e7a.", "verse": "Mt 11,28-30", "lectio": "Jesus convida ao descanso. O que voc\u00ea precisa entregar?", "practice": "Fa\u00e7a uma lista do que pesa e marque o que n\u00e3o depende de voc\u00ea.", "question": "O que pesa em voc\u00ea que n\u00e3o \u00e9 seu para carregar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('272da72e-2655-4fb8-852c-23383d4f8a62', 'c1c2c3d4-3030-4000-8000-000000000030', 14, 'Desapegar', 'Semana 2 — Desconstruir', '{"pch": "Enquanto voc\u00ea olha para tr\u00e1s\u2026 n\u00e3o enxerga o que est\u00e1 \u00e0 frente.", "verse": "Fl 3,13-14", "lectio": "Paulo esquece o que ficou para tr\u00e1s. O que voc\u00ea precisa deixar?", "practice": "Escolha uma mem\u00f3ria, h\u00e1bito ou v\u00ednculo para soltar hoje.", "question": "O que do passado ainda te define?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('86d859f0-cfea-4b42-a4b5-b15ae072728b', 'c1c2c3d4-3030-4000-8000-000000000030', 15, 'Nova Visão', 'Semana 3 — Reconstruir', '{"pch": "Voc\u00ea n\u00e3o precisa de uma nova chance\u2026 precisa de novos olhos.", "verse": "2Cor 5,17", "lectio": "Leia e pergunte: o que significa ser nova criatura para mim hoje?", "practice": "Escreva como seria seu dia se voc\u00ea acreditasse plenamente nisso.", "question": "O que mudaria se voc\u00ea se visse como Deus te v\u00ea?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c155855b-95d5-4fb8-9cd7-68739b6b56f2', 'c1c2c3d4-3030-4000-8000-000000000030', 16, 'Escolhas', 'Semana 3 — Reconstruir', '{"pch": "Toda manh\u00e3 voc\u00ea escolhe\u2026 mesmo quando acha que n\u00e3o.", "verse": "Dt 30,19", "lectio": "Deus coloca vida e morte diante de n\u00f3s. O que voc\u00ea escolhe hoje?", "practice": "Tome uma micro-decis\u00e3o que voc\u00ea adia h\u00e1 dias.", "question": "Qual escolha voc\u00ea tem evitado?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('022cabd4-752c-4df8-8e91-9e8fe44cdca1', 'c1c2c3d4-3030-4000-8000-000000000030', 17, 'Hábitos', 'Semana 3 — Reconstruir', '{"pch": "Disciplina n\u00e3o \u00e9 castigo\u2026 \u00e9 cuidado com quem voc\u00ea est\u00e1 se tornando.", "verse": "1Cor 9,27", "lectio": "Paulo disciplina o corpo. Qual \u00e1rea da sua vida precisa de ordem?", "practice": "Defina um micro-h\u00e1bito para os pr\u00f3ximos 7 dias.", "question": "Qual h\u00e1bito te aproxima de quem voc\u00ea quer ser?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d9150e85-aa75-4b79-8feb-ceeeb96760a3', 'c1c2c3d4-3030-4000-8000-000000000030', 18, 'Disciplina', 'Semana 3 — Reconstruir', '{"pch": "O que d\u00f3i agora\u2026 forma depois.", "verse": "Hb 12,11", "lectio": "A disciplina parece dolorosa, mas gera fruto. Qual fruto voc\u00ea busca?", "practice": "Pratique algo dif\u00edcil por 15 minutos hoje, conscientemente.", "question": "Qual disciplina voc\u00ea resiste mas sabe que precisa?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('459230b6-a949-4e59-96cd-1e04dfdb96c3', 'c1c2c3d4-3030-4000-8000-000000000030', 19, 'Foco', 'Semana 3 — Reconstruir', '{"pch": "Foco n\u00e3o \u00e9 ignorar o resto\u2026 \u00e9 saber o que importa agora.", "verse": "Fl 3,13-14", "lectio": "Paulo avan\u00e7a para o alvo. Qual \u00e9 o seu alvo neste momento?", "practice": "Elimine uma distra\u00e7\u00e3o por 24 horas.", "question": "O que merece sua aten\u00e7\u00e3o total hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7b5634a6-a6a0-43c7-8919-77729705818a', 'c1c2c3d4-3030-4000-8000-000000000030', 20, 'Constância', 'Semana 3 — Reconstruir', '{"pch": "Desistir \u00e9 f\u00e1cil\u2026 mas o fruto vem pra quem fica.", "verse": "Gl 6,9", "lectio": "N\u00e3o se canse de fazer o bem. Em que \u00e1rea voc\u00ea cansa r\u00e1pido?", "practice": "Recomece algo que voc\u00ea abandonou esta semana.", "question": "Onde voc\u00ea tem desistido cedo demais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('4281821b-5b55-4965-b5c5-4c01130eec6a', 'c1c2c3d4-3030-4000-8000-000000000030', 21, 'Identidade', 'Semana 3 — Reconstruir', '{"pch": "Voc\u00ea n\u00e3o \u00e9 o que fez\u2026 \u00e9 o que foi feito para ser.", "verse": "Ef 2,10", "lectio": "Somos obra de Deus. O que isso muda na forma como voc\u00ea se v\u00ea?", "practice": "Escreva: quem eu sou, sem t\u00edtulos, sem pap\u00e9is, sem m\u00e1scaras.", "question": "Quem voc\u00ea \u00e9 quando ningu\u00e9m est\u00e1 olhando?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('5dd229da-b343-49b7-9c7a-f79db3faf550', 'c1c2c3d4-3030-4000-8000-000000000030', 22, 'Presença', 'Semana 4 — Integrar', '{"pch": "Deus n\u00e3o est\u00e1 no destino\u2026 est\u00e1 no caminho.", "verse": "Sl 139,7-10", "lectio": "Leia e pergunte: em que momento do meu dia Deus esteve mais perto?", "practice": "Viva uma hora inteira com aten\u00e7\u00e3o plena ao presente.", "question": "Onde voc\u00ea sente a presen\u00e7a de Deus hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e1445250-0515-4257-8395-5e40727cc79b', 'c1c2c3d4-3030-4000-8000-000000000030', 23, 'Propósito', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o precisa inventar um prop\u00f3sito\u2026 precisa descobrir o que j\u00e1 foi plantado.", "verse": "Jr 29,11", "lectio": "Deus tem planos de paz. O que ressoa dentro de voc\u00ea ao ler isso?", "practice": "Liste 3 coisas que te d\u00e3o energia e alegria verdadeira.", "question": "O que te faz sentir vivo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d58e1b64-b4b6-4bd7-ae8a-9175a9b03814', 'c1c2c3d4-3030-4000-8000-000000000030', 24, 'Confiança', 'Semana 4 — Integrar', '{"pch": "Confiar n\u00e3o \u00e9 entender\u2026 \u00e9 caminhar mesmo sem ver.", "verse": "Sl 37,5", "lectio": "Entregue o seu caminho ao Senhor. O que voc\u00ea ainda segura?", "practice": "Entregue uma preocupa\u00e7\u00e3o em ora\u00e7\u00e3o e n\u00e3o a retome hoje.", "question": "Em que \u00e1rea da vida voc\u00ea precisa confiar mais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('0363689a-20b6-44e4-ab42-70ef3e29a688', 'c1c2c3d4-3030-4000-8000-000000000030', 25, 'Entrega', 'Semana 4 — Integrar', '{"pch": "A maior liberdade\u2026 \u00e9 querer o que Deus quer.", "verse": "Lc 22,42", "lectio": "Jesus no Gets\u00eamani: n\u00e3o a minha, mas a Tua vontade. O que isso significa pra voc\u00ea?", "practice": "Fa\u00e7a uma ora\u00e7\u00e3o de entrega: escreva o que voc\u00ea entrega hoje.", "question": "O que voc\u00ea ainda n\u00e3o entregou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
